<!doctype html><html lang="en"><meta charset="utf-8"><title>Manage feeds</title><main><h1>Feeds</h1><p><a href="<?= site_url('admin') ?>">Dashboard</a></p><?php if ($error = session()->getFlashdata('error')): ?><p role="alert"><?= esc($error) ?></p><?php endif; ?><form method="post"><?= csrf_field() ?><label>Feed URL <input name="url" type="url" required></label><button>Add feed</button></form><?php foreach ($feeds as $feed): ?><article><h2><?= esc($feed['feed_title']) ?></h2><p><?= esc($feed['feed_url']) ?> · <?= esc($feed['feed_status']) ?></p><?php if ($feed['feed_status'] === 'active'): ?><form method="post" action="<?= site_url('admin/feeds/' . $feed['feed_id'] . '/delete') ?>"><?= csrf_field() ?><button>Deactivate</button></form><?php endif; ?></article><?php endforeach; ?></main></html>
